from solution import starts_one_ends

import pytest
from hypothesis import given
import hypothesis.strategies as st


def reference_closed_form(n):
    if n == 1:
        return 1
    return 18 * (10 ** (n - 2))


def reference_arithmetic(n):
    # Independent arithmetic reference (no str conversion):
    # first digit via //, last digit via %
    total = 0
    start = 10 ** (n - 1)
    end = 10 ** n
    pow_first = 10 ** (n - 1)
    for i in range(start, end):
        first = i // pow_first
        last = i % 10
        if first == 1 or last == 1:
            total += 1
    return total


def test_single_digit_count_is_one():
    assert starts_one_ends(1) == 1


def test_two_digit_count_is_18():
    assert starts_one_ends(2) == 18


def test_three_digit_count_is_180():
    assert starts_one_ends(3) == 180


def test_four_digit_count_is_1800():
    assert starts_one_ends(4) == 1800


def test_five_digit_count_is_18000():
    assert starts_one_ends(5) == 18000


def test_closed_form_n1_through_n5():
    for n in [1, 2, 3, 4, 5]:
        assert starts_one_ends(n) == reference_closed_form(n)


@given(st.integers(min_value=1, max_value=4))
def test_matches_closed_form(n):
    assert starts_one_ends(n) == reference_closed_form(n)


@given(st.integers(min_value=1, max_value=4))
def test_matches_arithmetic_reference(n):
    assert starts_one_ends(n) == reference_arithmetic(n)


@given(st.integers(min_value=1, max_value=4))
def test_result_is_positive_int_within_total(n):
    result = starts_one_ends(n)
    assert type(result) == int
    total_n_digit = 9 * (10 ** (n - 1))
    assert 1 <= result <= total_n_digit


@given(st.integers(min_value=2, max_value=4))
def test_complement_count(n):
    # Numbers that neither start nor end with 1.
    result = starts_one_ends(n)
    total = 9 * (10 ** (n - 1))
    complement = total - result
    # first digit in {2..9} (8 options), last digit != 1 (9 options)
    expected_complement = 8 * 9 * (10 ** (n - 2))
    assert complement == expected_complement


@given(st.integers(min_value=1, max_value=3))
def test_tenfold_growth(n):
    # For n >= 2, count(n+1) == 10 * count(n).
    a = starts_one_ends(n)
    b = starts_one_ends(n + 1)
    if n == 1:
        assert a == 1
        assert b == 18
    else:
        assert b == 10 * a


@given(st.integers(min_value=2, max_value=4))
def test_inclusion_exclusion_decomposition(n):
    # start==1: 10**(n-1); end==1: 9*10**(n-2); both: 10**(n-2)
    result = starts_one_ends(n)
    start_with_1 = 10 ** (n - 1)
    end_with_1 = 9 * (10 ** (n - 2))
    both = 10 ** (n - 2)
    assert result == start_with_1 + end_with_1 - both
    assert result == start_with_1 + 8 * (10 ** (n - 2))
    # Must be strictly larger than each individual piece (for n>=2)
    # and strictly smaller than their sum.
    assert result > start_with_1
    assert result > end_with_1
    assert result < start_with_1 + end_with_1


@given(st.integers(min_value=1, max_value=4))
def test_strictly_increasing_with_n(n):
    # More digits => strictly more qualifying numbers.
    if n < 4:
        assert starts_one_ends(n + 1) > starts_one_ends(n)
